export function isWeekday(value: unknown): value is Weekday {
  return (
    value === 'mon' ||
    value === 'tue' ||
    value === 'wed' ||
    value === 'thu' ||
    value === 'fri' ||
    value === 'sat' ||
    value === 'sun'
  );
}

/** Whether `value` has the shape of a {@link WhenFileExists}; fields it does not name are not checked. */
export function isWhenFileExists(value: unknown): value is WhenFileExists {
  return (
    value === 'ask' || value === 'replace' || value === 'keep_existing' || value === 'keep_both'
  );
}

/** Whether `value` has the shape of a {@link WithdrawOutcome}; fields it does not name are not checked. */
export function isWithdrawOutcome(value: unknown): value is WithdrawOutcome {
  return value === 'withdrawn' || value === 'not_found' || value === 'already_started';
}

/** Whether `value` has the shape of a {@link WithdrawRequest}; fields it does not name are not checked. */
export function isWithdrawRequest(value: unknown): value is WithdrawRequest {
  return ((value1: unknown): boolean =>
    isRecord(value1) && typeof value1['handover_id'] === 'string')(value);
}
